command:
$ErrorActionPreference='Stop'; $dir=Join-Path $env:TEMP 'fly-dpi-probe'; if(Test-Path $dir){Remove-Item $dir -Recurse -Force}; New-Item $dir -ItemType Directory|Out-Null; $src=Join-Path $dir 'dpi_probe.cpp'; @'

#include <windows.h>
#include <vector>
#include <iostream>
#include <cstdint>
#include <cstdlib>
static const UINT32 vals[]={100,125,150,175,200,225,250,300,350,400,450,500};
struct DpiGet{DISPLAYCONFIG_DEVICE_INFO_HEADER header;std::int32_t minRel,curRel,maxRel;};
struct DpiSet{DISPLAYCONFIG_DEVICE_INFO_HEADER header;std::int32_t scaleRel;};
bool paths(std::vector<DISPLAYCONFIG_PATH_INFO>& out){
 UINT32 np=0,nm=0;
 if(GetDisplayConfigBufferSizes(QDC_ONLY_ACTIVE_PATHS,&np,&nm)!=ERROR_SUCCESS)return false;
 std::vector<DISPLAYCONFIG_PATH_INFO> p(np);
 std::vector<DISPLAYCONFIG_MODE_INFO> m(nm);
 if(QueryDisplayConfig(QDC_ONLY_ACTIVE_PATHS,&np,p.data(),&nm,m.data(),nullptr)!=ERROR_SUCCESS)return false;
 p.resize(np);out=std::move(p);return !out.empty();
}
bool info(LUID a,UINT32 id,UINT32& cur,UINT32& rec,UINT32& maxv,int& minRel,int& curRel,int& maxRel){
 DpiGet q{}; q.header.type=(DISPLAYCONFIG_DEVICE_INFO_TYPE)-3;q.header.size=sizeof(q);q.header.adapterId=a;q.header.id=id;
 auto rc=DisplayConfigGetDeviceInfo(&q.header);
 std::cout<<"GET_RC="<<rc<<" PACKET="<<sizeof(q)<<"\n";
 if(rc!=ERROR_SUCCESS)return false;
 minRel=q.minRel;curRel=q.curRel;maxRel=q.maxRel;
 int base=std::abs(q.minRel);
 if(base<0||base>=int(sizeof(vals)/sizeof(vals[0])))return false;
 int ci=base+q.curRel, mi=base+q.maxRel;
 if(ci<0||mi<0||ci>=int(sizeof(vals)/sizeof(vals[0]))||mi>=int(sizeof(vals)/sizeof(vals[0])))return false;
 cur=vals[ci];rec=vals[base];maxv=vals[mi];return true;
}
int wmain(){
 std::vector<DISPLAYCONFIG_PATH_INFO> p;
 if(!paths(p)){std::cout<<"PATHS_FAIL\n";return 2;}
 std::cout<<"ACTIVE_PATHS="<<p.size()<<"\n";
 for(size_t i=0;i<p.size();++i){
  UINT32 cur=0,rec=0,maxv=0;int mn=0,cr=0,mx=0;
  bool ok=info(p[i].sourceInfo.adapterId,p[i].sourceInfo.id,cur,rec,maxv,mn,cr,mx);
  std::cout<<"PATH "<<i<<" SOURCE_ID="<<p[i].sourceInfo.id<<" OK="<<ok;
  if(ok)std::cout<<" MIN=100 CURRENT="<<cur<<" RECOMMENDED="<<rec<<" MAX="<<maxv<<" REL="<<mn<<","<<cr<<","<<mx;
  std::cout<<"\n";
 }
 return 0;
}

'@ | Set-Content $src -Encoding utf8; $vs=& "${env:ProgramFiles(x86)}\Microsoft Visual Studio\Installer\vswhere.exe" -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath; if(-not $vs){throw 'VS not found'}; $vc=Join-Path $vs 'VC\Auxiliary\Build\vcvars64.bat'; cmd /c "call \"$vc\" >nul && cl /nologo /std:c++17 /EHsc \"$src\" /Fe:\"$dir\dpi_probe.exe\" user32.lib"; if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}; & "$dir\dpi_probe.exe"; $rc=$LASTEXITCODE; Remove-Item $dir -Recurse -Force; exit $rc
